package edu.course.shop.service;

import com.google.gson.Gson;
import edu.course.shop.*;
import edu.course.shop.model.*;
import edu.course.shop.persistence.*;
import edu.course.shop.ui.*;
import javafx.application.Platform;
import javafx.scene.*;
import javafx.scene.chart.AreaChart;
import javafx.scene.control.*;
import javafx.scene.input.*;
import javafx.scene.layout.*;
import javafx.stage.Stage;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;
import java.math.BigDecimal;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.BooleanSupplier;

/** Real-window admin motion, reviewed changes and optimistic Undo; all data and provider replies are fixtures. */
public final class AdminMotionUiSmoke {
    private static Scene scene;private static Stage stage;private static int checks;
    private static <T>T fx(Callable<T> work)throws Exception{FutureTask<T> future=new FutureTask<>(()->{if(scene!=null){scene.getRoot().applyCss();scene.getRoot().layout();}return work.call();});Platform.runLater(future);return future.get(20,TimeUnit.SECONDS);}
    private static void waitFor(BooleanSupplier condition)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(20);while(!fx(condition::getAsBoolean)){if(System.nanoTime()>end)throw new AssertionError("Timed out waiting for admin motion");Thread.sleep(25);}}
    private static void check(boolean ok,String text){if(!ok)throw new AssertionError(text);checks++;System.out.println("PASS "+text);}
    private static void press(String id)throws Exception{fx(()->{((Button)scene.lookup("#"+id)).fire();return null;});}
    private static AreaChart<?,?> chart(){return (AreaChart<?,?>)scene.lookup("#admin-revenue-chart");}
    private static TextField stock(){return scene.getRoot().lookupAll(".workspace-inline-field").stream().filter(n->n instanceof TextField field&&"Stock quantity".equals(field.getAccessibleText())).map(n->(TextField)n).findFirst().orElseThrow();}
    private static double opacity(){return scene.lookup("#ai-manager-terminal-dot-0").getOpacity();}
    private static GeminiAssistant.Reply reply(Object part){return new GeminiAssistant.Reply(200,new Gson().toJson(Map.of("candidates",List.of(Map.of("finishReason","STOP","content",Map.of("parts",List.of(part)))))));}
    private static void shot(Path out)throws Exception{fx(()->{var image=scene.getRoot().snapshot(null,null);BufferedImage png=new BufferedImage((int)image.getWidth(),(int)image.getHeight(),BufferedImage.TYPE_INT_ARGB);for(int y=0;y<png.getHeight();y++)for(int x=0;x<png.getWidth();x++)png.setRGB(x,y,image.getPixelReader().getArgb(x,y));ImageIO.write(png,"png",out.toFile());return null;});}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(args[0]);Files.createDirectories(out);DatabaseManager db=new DatabaseManager(out.resolve("motion-"+System.nanoTime()+".db"));db.initialize();ProductRepository pr=new ProductRepository();OrderRepository or=new OrderRepository();Services services=new Services(new AuthService(db,new UserRepository()),new ProductService(db,pr),new CheckoutService(db,pr,or),new OrderService(db,or),new AdminService(db,new AdminRepository()),new ProductReviewService(db,new ProductReviewRepository()));
        User admin=services.auth().login("admin","admin123"),customer=services.auth().login("customer","customer123");try(var c=db.open();var s=c.createStatement()){s.executeUpdate("DELETE FROM products");}
        byte[] art;try(var in=AdminMotionUiSmoke.class.getResourceAsStream("/images/category-gpu.png")){art=in.readAllBytes();}
        services.products().save(admin,0,"Aurora graphics card",Category.PC_PARTS,new BigDecimal("199.00"),3,true,"",art,List.of(),"Memory: 8 GB");Product product=services.products().search(admin,"Aurora",null).getFirst();
        try(var c=db.open();var insert=c.prepareStatement("INSERT INTO orders(customer_id,created_at,address,payment_method,payment_status,total_cents) VALUES(?,?,'Fixture','Demo','PAID',?)")){for(int i=0;i<6;i++){insert.setLong(1,customer.getId());insert.setString(2,Instant.now().minusSeconds(i*86400L).toString());insert.setLong(3,(i+1)*10000L);insert.executeUpdate();}}
        CountDownLatch ready=new CountDownLatch(1);Platform.startup(ready::countDown);ready.await();Platform.setImplicitExit(false);
        try{
            fx(()->{Motion.reducedProperty().set(false);stage=new Stage();scene=new Scene(new StackPane(),1280,900);scene.getStylesheets().add(AdminMotionUiSmoke.class.getResource("/shop.css").toExternalForm());stage.setScene(scene);stage.show();new ShopWindow(stage,services).showLogin();scene.getRoot().applyCss();scene.getRoot().layout();((TextField)scene.lookup("#username")).setText("admin");((PasswordField)scene.lookup("#password")).setText("admin123");((Button)scene.lookup("#login")).fire();return null;});
                        waitFor(()->chart()!=null&&!chart().getData().isEmpty());fx(()->{
                for(Node p=chart().getParent();p!=null;p=p.getParent())if(p instanceof ScrollPane scroll){Node viewport=scroll.lookup(".viewport");double offset=chart().localToScene(chart().getLayoutBounds()).getMinY()-viewport.localToScene(viewport.getLayoutBounds()).getMinY()-40;double range=scroll.getContent().getLayoutBounds().getHeight()-scroll.getViewportBounds().getHeight();if(range>0)scroll.setVvalue(Math.max(0,Math.min(1,scroll.getVvalue()+offset/range)));}
                ((ToggleButton)scene.lookup("#admin-chart-weekly")).fire();return null;});waitFor(()->Boolean.TRUE.equals(chart().getProperties().get("forge.revenueDrawing")));
            double total=fx(()->chart().getData().getFirst().getData().stream().mapToDouble(p->((Number)p.getYValue()).doubleValue()).sum());check(total==2100,"Drawing animation uses exact source values from the first frame");shot(out.resolve("01-chart-drawing.png"));waitFor(()->!Boolean.TRUE.equals(chart().getProperties().get("forge.revenueDrawing")));check(fx(()->chart().getData().getFirst().getData().stream().mapToDouble(p->((Number)p.getYValue()).doubleValue()).sum())==total,"Finishing the line reveal does not change revenue values");
            fx(()->{((ToggleButton)scene.lookup("#admin-chart-monthly")).fire();return null;});waitFor(()->Boolean.TRUE.equals(chart().getProperties().get("forge.revenueDrawing")));fx(()->{Motion.reducedProperty().set(true);check(!Boolean.TRUE.equals(chart().getProperties().get("forge.revenueDrawing")),"Reduce motion immediately restores the complete graph");Motion.reducedProperty().set(false);return null;});
            press("nav-inventory");waitFor(()->scene.lookup("#admin-table") instanceof TableView<?> table&&table.getItems().size()==1);waitFor(()->scene.lookup("#admin-nav-indicator").getTranslateY()>100);check(true,"Sidebar indicator follows the selected module");
            fx(()->{stock().setText("oops");stock().fireEvent(new javafx.event.ActionEvent());check(stock().getText().equals("oops"),"Invalid inventory input is preserved for correction");check(scene.getRoot().lookupAll(".workspace-inline-error").stream().anyMatch(Node::isVisible),"Inventory validation is displayed beside the field");return null;});check(services.products().get(product.getId()).getStock()==3,"Invalid input leaves stored stock unchanged");
            fx(()->{stock().setText("7");stock().fireEvent(new javafx.event.ActionEvent());check(stock().isDisabled(),"Only the saving field is locked against duplicate commits");check(!scene.lookup("#admin-nav-orders").isDisabled(),"Navigation remains responsive during an inventory save");return null;});waitFor(()->services.products().get(product.getId()).getStock()==7);waitFor(()->scene.lookup("#admin-toast-undo")!=null);check(fx(()->scene.getRoot().lookupAll(".workspace-inline-saved").stream().anyMatch(Node::isVisible)),"Saved feedback appears beside the edited inventory field");shot(out.resolve("02-stock-saved.png"));press("admin-toast-undo");waitFor(()->services.products().get(product.getId()).getStock()==3);check(true,"Undo safely restores the previous inventory numbers");
            waitFor(()->stock().getText().equals("3"));fx(()->{stock().setText("9");stock().fireEvent(new javafx.event.ActionEvent());return null;});waitFor(()->services.products().get(product.getId()).getStock()==9);waitFor(()->scene.lookup("#admin-toast-undo")!=null);services.products().updateInventoryNumbers(admin,services.products().get(product.getId()),product.getPrice(),2);press("admin-toast-undo");waitFor(()->scene.lookup("#admin-toast")!=null&&scene.lookup("#admin-toast").getAccessibleText().startsWith("Could not undo"));check(services.products().get(product.getId()).getStock()==2,"Undo refuses to overwrite a newer stock change");
            fx(()->{CheckBox select=scene.getRoot().lookupAll(".check-box").stream().filter(n->n instanceof CheckBox c&&"Select Aurora graphics card".equals(c.getAccessibleText())).map(n->(CheckBox)n).findFirst().orElseThrow();select.fire();check(scene.lookup("#admin-bulk-actions").isVisible(),"Selecting a product reveals the bulk action bar");return null;});waitFor(()->scene.lookup("#admin-bulk-actions").getOpacity()>.99);check(true,"Bulk actions settle at full opacity");
            fx(()->{scene.lookup("#new-product").requestFocus();return null;});press("new-product");waitFor(()->scene.lookup("#admin-product-modal")!=null);fx(()->{scene.lookup("#admin-workspace").fireEvent(new KeyEvent(KeyEvent.KEY_PRESSED,"","",KeyCode.TAB,false,false,false,false));Node focus=scene.getFocusOwner();boolean inside=false;for(Node node=focus;node!=null;node=node.getParent())if(node==scene.lookup("#admin-product-modal"))inside=true;check(inside,"Tab stays within the active product dialog");scene.lookup("#admin-workspace").fireEvent(new KeyEvent(KeyEvent.KEY_PRESSED,"","",KeyCode.ESCAPE,false,false,false,false));return null;});waitFor(()->scene.lookup("#admin-modal")==null);waitFor(()->scene.getFocusOwner()==scene.lookup("#new-product"));check(true,"Closing the dialog restores keyboard focus to its opener");
            press("admin-nav-ai-manager");waitFor(()->scene.lookup("#ai-manager-page")!=null);CountDownLatch drafting=new CountDownLatch(1),release=new CountDownLatch(1);
            GeminiAssistant mock=new GeminiAssistant(new GeminiAssistant.Config("test-fixture","gemini-test",true),request->{
                if(AiManagerServiceTest.requestBody(request).contains("functionDeclarations"))return reply(Map.of("functionCall",Map.of("name","fix_content","args",Map.of("ids",List.of(product.getId())))));
                drafting.countDown();if(!release.await(60,TimeUnit.SECONDS))throw new IllegalStateException("Fixture release timed out");
                String draft=new Gson().toJson(Map.of("drafts",List.of(Map.of("id",product.getId(),"description","A reviewed graphics card fixture with 8 GB recorded memory.","specifications","","exactModel",false,"sources",List.of(),"note","Based on recorded facts."))));
                return reply(Map.of("text",draft));
            });
            fx(()->{AiManagerView old=(AiManagerView)scene.lookup("#ai-manager-page");BorderPane host=(BorderPane)old.getParent();old.dispose();host.setCenter(new AiManagerView(admin,services,mock));return null;});waitFor(()->scene.lookup("#ai-manager-chip-fix")!=null);press("ai-manager-chip-fix");check(drafting.await(20,TimeUnit.SECONDS),"Mocked command reaches the actual content drafting stage");double initial=fx(AdminMotionUiSmoke::opacity);waitFor(()->Math.abs(opacity()-initial)>.1);check(true,"Terminal dots animate while a command is processing");check(fx(()->((VBox)scene.lookup("#ai-manager-activity")).getChildren().stream().anyMatch(n->n instanceof Label l&&l.getText().contains("Drafting content for 1"))),"Terminal reports real pipeline stages instead of invented progress");shot(out.resolve("03-command-processing.png"));
            fx(()->{stage.hide();return null;});double hidden=fx(AdminMotionUiSmoke::opacity);Thread.sleep(180);check(fx(AdminMotionUiSmoke::opacity)==hidden,"Hidden windows stop terminal activity animation");fx(()->{stage.show();Motion.reducedProperty().set(true);return null;});check(fx(()->scene.lookup("#ai-manager-terminal-dot-0").getOpacity()==1&&scene.lookup("#ai-manager-terminal-dot-0").getTranslateY()==0),"Reduce motion uses a static busy indicator");fx(()->{Motion.reducedProperty().set(false);return null;});release.countDown();waitFor(()->scene.lookup("#ai-manager-apply")!=null);check(fx(()->scene.getRoot().lookupAll(".manager-before").size()==1&&scene.getRoot().lookupAll(".manager-after").size()==1),"AI content preview compares before and editable proposed values");check(services.products().get(product.getId()).getDescription().isBlank(),"AI preview leaves the database unchanged before approval");waitFor(()->scene.lookup("#ai-manager-results").getOpacity()>.99);check(fx(()->scene.lookup("#ai-manager-apply").localToScene(scene.lookup("#ai-manager-apply").getLayoutBounds()).getMaxY()<scene.getHeight()-45),"Reviewed changes and the Apply action are brought into view");shot(out.resolve("04-before-after-preview.png"));double stopped=fx(AdminMotionUiSmoke::opacity);Thread.sleep(200);check(fx(AdminMotionUiSmoke::opacity)==stopped,"Terminal dots stop after a command finishes");press("ai-manager-apply");waitFor(()->scene.lookup("#ai-manager-success")!=null);check(!services.products().get(product.getId()).getDescription().isBlank(),"Explicitly reviewed AI changes still save successfully");check(fx(()->scene.lookup("#admin-toast")!=null),"Completed AI changes show a compact success notification");
            press("admin-nav-orders");waitFor(()->scene.lookup("#admin-report-orders")!=null);check(fx(()->scene.lookup("#ai-manager-page")==null),"Switching modules disposes the previous manager and activity indicator");
            System.out.println("ADMIN MOTION PASS: "+checks+" assertions; no network requests");
        }finally{Platform.exit();}
    }
}